"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference='"'Stop'
"'$gets=0;$reads=0;$stage='"'PRECHECK'
try{
if((Get-Location).Path-ne'D:\\EliteSync-v10'-or(git branch --show-current)-ne'main'-or(git rev-parse HEAD)-ne'cf8bfaa4a03b8c9a682105617b185141904413be'){throw 'AUTHORITY'}
"'$s=Get-Content -LiteralPath '"'EVIDENCE/APP-M5-81-PINNED-OWN-EXTENSION-API-EVIDENCE/workspace-before.json' -Raw|ConvertFrom-Json
"'$n=@(git -c core.quotepath=false status --porcelain=v1|ForEach-Object{$_.Substring(3)})
if($s.Count-ne238-or$s.Paths.Count-ne238-or@($s.Paths|Where-Object{$_ -notin $n}).Count-ne0){throw '"'SNAPSHOT'}
if(Test-Path -LiteralPath 'EVIDENCE/APP-M5-81-PINNED-OWN-EXTENSION-API-EVIDENCE/own-api-evidence.md'){throw 'TARGET'}
"'$d=Get-Item -LiteralPath '"'EVIDENCE/APP-M5-81-PINNED-OWN-EXTENSION-API-EVIDENCE'
while("'$null-ne$d){if($d-isnot[IO.DirectoryInfo]-or($d.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw '"'ANCESTOR'};"'$d=$d.Parent}
$handler=[Net.Http.HttpClientHandler]::new()
$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$handler.UseDefaultCredentials=$false;$handler.Credentials=$null;$handler.UseProxy=$false
$client=[Net.Http.HttpClient]::new($handler)
$client.Timeout=[TimeSpan]::FromSeconds(30);$client.MaxResponseContentBufferSize=1048576
$utf=[Text.UTF8Encoding]::new($false,$true)
$urls=@('"'https://docs.gradle.org/8.14/javadoc/org/gradle/api/Project.html','https://docs.gradle.org/8.14/javadoc/org/gradle/api/plugins/ExtensionContainer.html')
"'$parts=[Collections.Generic.List[string]]::new()
for($i=0;$i-lt2;$i++){
$stage="HTTP_$($i+1)";$gets++
$r=$client.GetAsync($urls[$i]).GetAwaiter().GetResult()
if([int]$r.StatusCode-ne200-or$r.RequestMessage.RequestUri.AbsoluteUri-ne$urls[$i]){throw '"'HTTP_IDENTITY'}
"'$stage="READ_$($i+1)";$reads++
$b=$r.Content.ReadAsByteArrayAsync().GetAwaiter().GetResult()
if($b.Length-gt1048576){throw '"'SIZE'}
"'$t=$utf.GetString($b)
$sha=[Security.Cryptography.SHA256]::Create()
try{$h=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('"'-','')}finally{"'$sha.Dispose()}
$parts.Add("SOURCE $($i+1) URL=$($urls[$i]) status=200 bytes=$($b.Length) SHA256=$h strictUTF8=true GET=1 responseRead=1")
$name=if($i-eq0){'"'getRootProject'}else{'getExtraProperties'}
"'$pat='"'<section class=\"detail\" id=\"('+[regex]::Escape("'$name)+'"'\\(\\))\">([\\s\\S]*?)</section>'
"'$m=[regex]::Match($t,$pat)
if($m.Success){$raw=$m.Groups[2].Value;$plain=[Net.WebUtility]::HtmlDecode([regex]::Replace($raw,'"'<["'^>]+>'"',' '));"'$parts.Add("ANCHOR=$($m.Groups[1].Value) TEXT=$([regex]::Replace($plain,'"'\\s+',' ').Trim())\")}else{"'$parts.Add("METHOD $name UNKNOWN")}
if($i-eq0){
$m=[regex]::Match($t,'"'<div class=\"type-signature\">([\\s\\S]*?)</div>')
if("'$m.Success){$plain=[Net.WebUtility]::HtmlDecode([regex]::Replace($m.Groups[1].Value,'"'<["'^>]+>'"',' '));"'$parts.Add("TYPE_SIGNATURE TEXT=$([regex]::Replace($plain,'"'\\s+',' ').Trim())\")}else{"'$parts.Add('"'TYPE_SIGNATURE UNKNOWN')}
"'$m=[regex]::Match($t,'"'<h3 id=\"methods-inherited-from-class-org.gradle.api.plugins.ExtensionAware\">([\\s\\S]*?)</code>')
if("'$m.Success){$raw=$m.Value;$link=[regex]::Match($raw,'"'<a href=\"(["'^"]*#getExtensions'"\\(\\))\"["'^>]*>getExtensions</a>'"');"'$plain=[Net.WebUtility]::HtmlDecode([regex]::Replace($raw,'"'<["'^>]+>'"',' '));"'$parts.Add("INHERITED_CONTEXT TEXT=$([regex]::Replace($plain,'"'\\s+',' ').Trim())\");if("'$link.Success){$parts.Add("GET_EXTENSIONS_HREF=$($link.Groups[1].Value)")}else{$parts.Add('"'GET_EXTENSIONS_HREF UNKNOWN')}}else{"'$parts.Add('"'INHERITED_CONTEXT UNKNOWN')}
}
"'$r.Dispose()
}
$client.Dispose()
$out="A_OK main HEAD=cf8bfaa4a03b8c9a682105617b185141904413be old=238 missing=0 status=$($n.Count) targetAbsent=true ordinaryFullAncestors=true GET=$gets responseRead=$reads"+[Environment]::NewLine+[string]::Join([Environment]::NewLine,$parts)
if($utf.GetByteCount($out)-gt8192-or$out.Length-gt10000){$stage='"'OUTPUT';throw 'LIMIT'}
[Console]::WriteLine("'$out)
}catch{
[Console]::WriteLine("A_FAIL stage=$stage GET=$gets responseRead=$reads exception=$($_.Exception.GetType().FullName) message=$($_.Exception.Message)")
exit 1
}'

